/* cppi::1cbab092aed1d43f6d54504e9f6baa135c63f6196606f109b707d02ab7fa701f */
SELECT COUNT(*) FROM (SELECT * FROM (
select business_date, cppib_sec_id AS cppib_id,  from_currency_code AS from_currency, 
to_currency_code AS to_currency, type AS instrument_type, sub_type AS instrument_sub_type,
bid_value, askvalue AS ask_value, mid_value AS mid_value, business_date AS rate_date,
price_source_code AS price_source from market.cppib_rates
where business_date = date('2025-06-25') AND "type" = 'CURRENCY' AND sub_type = 'CROSS_RATE' AND price_source_code = 'WM Company'
) z_q WHERE from_currency IN ('CAD')
) dbvrcnt

/* cppi::8f06face2518f1aeb65417053d75c186ffa8e3c63d5fe05d68efc374a07a71d7 */
/* QuickSight a0e78d4f-446b-4ebb-a653-2ac706d6749e */
SELECT "cedc0063-a6c4-46b7-befb-c175092706ad.cppib_security_id"
FROM (
SELECT "cppib_security_id" AS "cedc0063-a6c4-46b7-befb-c175092706ad.cppib_security_id", DENSE_RANK() OVER (PARTITION BY "cppib_security_id" ORDER BY "cppib_security_id" NULLS FIRST) AS "$RANK_1"
FROM "AwsDataCatalog"."risk_prod"."rmv_position"
WHERE "investment_dept" = 'Credit Investments' AND "cppib_security_id" IN ('AWS_SSO_QS_Author_Risk_Prod', 'O365_E5_Users', 'AWS_SSO_QS_Viewer_Risk')
GROUP BY "cppib_security_id"
) AS "t"
WHERE "$RANK_1" <= 1001

